// if (o instanceof String s || s.length() > 3) { }
// Blad kompilacji: cannot find symbol s.length()
// || jest leniwe: prawa strona jest oceniana TYLKO wtedy, gdy lewa strona (o instanceof String s)
// jest FALSE. A skoro jest false, oznacza to, ze 'o' NIE JEST Stringiem - wiec zmienna 's' nie
// zostala przypisana w tej galezi. Kompilator, pilnujac 'definite assignment', odrzuca kod, w
// ktorym zmienna moglaby byc uzyta bez gwarancji, ze zostala wczesniej ustawiona.

static String classify(Object o) {
    if (o instanceof String s) return "String: " + s;
    else if (o instanceof Integer i) return "Integer: " + i;
    else if (o instanceof Double d) return "Double: " + d;
    else if (o instanceof Boolean b) return "Boolean: " + b;
    else return "nieznany typ";
}
Object[] items = { "x", 1, 2.5, true, 5L };
for (Object item : items) System.out.println(classify(item));

