static void demo(Object o) {
    String s = "zewnetrzne";
    // if (o instanceof String s) { } // BLAD: variable s is already defined in method demo(Object)
    if (o instanceof String inner) {
        System.out.println(inner);
    }
    System.out.println(s);
}
// Naprawa: zmienna wzorca 'inner' ma inna nazwe niz juz istniejaca lokalna zmienna 's'.

static void reassignDemo(Object o) {
    if (o instanceof String s) {
        System.out.println("Przed: " + s);
        s = s.trim().toLowerCase();
        System.out.println("Po: " + s);
    }
}
reassignDemo("  ALA  ");
// Kompiluje sie bez bledu - zmienna wzorca 's' zachowuje sie jak zwykla zmienna lokalna,
// NIE jest niejawnie final (w odroznieniu od zmiennych przechwytywanych przez lambdy).

// obj instanceof List<String> list - NIELEGALNE, blad kompilacji "unchecked or unsafe operation"
// (a scisle: nie da sie sprawdzic samego <String> w runtime, bo Java kasuje parametry
// generyczne po kompilacji - to type erasure z Lesson06 rozdzialu Generics). instanceof moze
// sprawdzic TYLKO surowy typ (List), nie jego argument typu.
static void demo(Object obj) {
    if (obj instanceof List<?> list) {
        System.out.println("Lista o rozmiarze " + list.size());
    }
}
demo(java.util.List.of("a", "b"));

