static void processOrder(Object customerId, Object amount) {
    if (!(customerId instanceof String id)) {
        System.out.println("Blad: customerId musi byc Stringiem");
        return;
    }
    if (!(amount instanceof Double amt) || amt <= 0) {
        System.out.println("Blad: amount musi byc dodatnim Double");
        return;
    }
    System.out.println("Zamowienie przyjete dla " + id + " na kwote " + amt);
}
processOrder("KL001", 199.99);
processOrder(123, 199.99);
processOrder("KL001", -5.0);

