// LEGACY:
static boolean validateLegacy(Object payload) {
    if (payload instanceof String) {
        String s = (String) payload;
        return !s.isEmpty();
    }
    if (payload instanceof Integer) {
        Integer i = (Integer) payload;
        return i > 0;
    }
    if (payload instanceof Double) {
        Double d = (Double) payload;
        return d > 0;
    }
    return false;
}

// ZREFAKTORYZOWANE:
static boolean validateModern(Object payload) {
    if (payload instanceof String s) return !s.isEmpty();
    if (payload instanceof Integer i) return i > 0;
    if (payload instanceof Double d) return d > 0;
    return false;
}
// Wersja zrefaktoryzowana eliminuje 3 osobne jawne rzutowania, jest krotsza i czytelniejsza.

static void demo(Object obj) {
    if (obj instanceof String s) {
        System.out.println(s.length());
    } else if (obj instanceof Integer i) {
        System.out.println(i * 2);
        // System.out.println(s); // BLAD: s nie istnieje tutaj
    }
}
// Galaz else if wykonuje sie TYLKO, gdy pierwszy warunek (obj instanceof String s) byl FALSE -
// czyli obj na pewno NIE jest Stringiem, wiec kompilator wie, ze 's' nigdy nie zostalo
// przypisane w tej galezi i odmawia dostepu do niej.

static String combine(Object a, Object b) {
    if (!(a instanceof String s)) return "blad A";
    if (!(b instanceof Integer i)) return "blad B";
    return s + i;
}
System.out.println(combine("wynik:", 5));
System.out.println(combine(1, 5));
System.out.println(combine("wynik:", "nie liczba"));

static String summarize(Object o) {
    if (o instanceof int[] arr) {
        int sum = 0;
        for (int x : arr) sum += x;
        return "suma: " + sum;
    } else if (o instanceof String[] arr) {
        return String.join(", ", arr);
    }
    return "nieznany typ";
}
System.out.println(summarize(new int[]{1,2,3}));
System.out.println(summarize(new String[]{"a","b","c"}));

interface ShapeX {}
class CircleX implements ShapeX { double r; CircleX(double r) { this.r = r; } }
class SquareX implements ShapeX { double s; SquareX(double s) { this.s = s; } }
class TriangleX implements ShapeX { double b, h; TriangleX(double b, double h) { this.b = b; this.h = h; } }

static String describe(ShapeX shape) {
    if (shape instanceof CircleX c) return "Kolo r=" + c.r;
    else if (shape instanceof SquareX s) return "Kwadrat s=" + s.s;
    else if (shape instanceof TriangleX t) return "Trojkat b=" + t.b;
    else return "nieznany";
}
// Nawet gdyby ShapeX byl sealed permits CircleX, SquareX, TriangleX - ten lancuch if/else-if
// i tak NIE bylby sprawdzany przez kompilator pod katem kompletnosci. Te gwarancje daje
// dopiero switch pattern matching z Lekcji 21.

List<Object> mixed = List.of("a", 1, "bb", 2.0, "ccc");
List<String> result = mixed.stream()
    .filter(o -> o instanceof String s && s.length() > 1)
    .map(o -> (String) o)
    .toList();
System.out.println(result);
// Zmienna 's' zdefiniowana WEWNATRZ lambdy .filter(...) ma zasieg OGRANICZONY do TEJ lambdy -
// .map(...) to CALKOWICIE OSOBNA lambda z wlasnym zasiegiem, wiec trzeba tam ponownie
// rzutowac (Object) o na (String), mimo ze logicznie 'wiemy' juz, ze to String.

record PointX(int x, int y) {}

static void printPoint(Object o) {
    if (o instanceof PointX p) {
        int x = p.x();
        int y = p.y();
        System.out.println("(" + x + ", " + y + ")");
    }
}
printPoint(new PointX(3, 4));
// Zapowiedz Lekcji 21: record pattern pozwoli zapisac to jeszcze krocej -
// if (o instanceof PointX(int x, int y)) { System.out.println("(" + x + ", " + y + ")"); }
// bez posredniej zmiennej 'p' i wywolan akcesorow x()/y().

// ANTY-WZORZEC:
static void badWay(Object o) {
    if (o instanceof String) {
        System.out.println("To String");
    }
    if (o instanceof String) {
        String s = (String) o;
        System.out.println(s.length());
    }
}

// POPRAWIONE:
static void goodWay(Object o) {
    if (o instanceof String s) {
        System.out.println("To String");
        System.out.println(s.length());
    }
}
// Powtorne sprawdzanie tego samego typu na tym samym obiekcie to code smell - marnuje czas
// (dwukrotna kontrola instanceof) i jest podatne na bledy, gdyby ktos zmienil warunek w
// jednym miejscu, a zapomnial w drugim.

class ValidationException extends RuntimeException { ValidationException(String m) { super(m); } }
class NetworkException extends RuntimeException { NetworkException(String m) { super(m); } }

static void handle(Runnable action) {
    try {
        action.run();
    } catch (Exception e) {
        if (e instanceof ValidationException ve) {
            System.out.println("Blad walidacji: " + ve.getMessage());
        } else if (e instanceof NetworkException ne) {
            System.out.println("Blad sieci: " + ne.getMessage());
        }
    }
}
handle(() -> { throw new ValidationException("zly format"); });
handle(() -> { throw new NetworkException("timeout"); });

static <T> java.util.Optional<T> safeCast(Object obj, Class<T> type) {
    if (type.isInstance(obj)) {
        return java.util.Optional.of(type.cast(obj));
    }
    return java.util.Optional.empty();
}
System.out.println(safeCast("tekst", String.class));
System.out.println(safeCast(123, String.class));
// Pattern matching instanceof (np. 'o instanceof String s') wymaga, by typ byl LITERALEM
// ZNANYM W CZASIE KOMPILACJI (String, Integer itd.) - nie da sie napisac 'o instanceof clazz s',
// gdzie clazz to zmienna Class<?>. safeCast pokazuje odpowiednik dla typu dynamicznego, oparty
// na refleksyjnych Class.isInstance()/Class.cast() z Lesson15.

class BigSquareX extends SquareX { BigSquareX(double s) { super(s); } }

static String fullDescription(ShapeX shape) {
    if (shape instanceof CircleX c) return "Kolo r=" + c.r;
    else if (shape instanceof BigSquareX bs) return "DUZY kwadrat s=" + bs.s;
    else if (shape instanceof SquareX s) return "Kwadrat s=" + s.s;
    else if (shape instanceof TriangleX t) return "Trojkat b=" + t.b;
    else return "nieznany ksztalt";
}
ShapeX[] shapes = { new CircleX(2), new SquareX(3), new BigSquareX(10), new TriangleX(4,5), new CircleX(1) };
for (ShapeX s : shapes) System.out.println(fullDescription(s));
// WAZNE: gdyby BigSquareX byl sprawdzany PO SquareX, nigdy nie zostalby wykryty - kazda
// instancja BigSquareX przechodzi TAKZE 'instanceof SquareX' (dziedziczenie).
